SELECT "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.year" AS "year", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.month" AS "month", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.billing_period" AS "billing_period", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.usage_date" AS "usage_date", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.payer_account_id" AS "payer_account_id", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.linked_account_id" AS "linked_account_id", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.resource_id" AS "resource_id", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.product_code" AS "product_code", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.operation" AS "operation", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.region" AS "region", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.charge_type" AS "charge_type", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.pricing_unit" AS "pricing_unit", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.usage_quantity" AS "usage_quantity", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.unblended_cost" AS "unblended_cost", "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.public_cost" AS "public_cost", "t0"."4559aa95-4a54-4998-800b-5fd03af260ea.account_id" AS "account_id", "t0"."4559aa95-4a54-4998-800b-5fd03af260ea.parent_account_id" AS "parent_account_id", "t0"."4559aa95-4a54-4998-800b-5fd03af260ea.account_name" AS "account_name", "t0"."4559aa95-4a54-4998-800b-5fd03af260ea.account_email_id" AS "account_email_id", "t1"."e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.account_id" AS "account_id[organization_map]", "t1"."e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.account_name" AS "account_name[organization_map]", "t1"."e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.ou" AS "ou", "t1"."e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.ou_id" AS "ou_id", "t1"."e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.payer_org_account_id" AS "payer_org_account_id", "t1"."e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.management_account_id" AS "management_account_id"
FROM (
SELECT "year" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.year", "month" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.month", "billing_period" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.billing_period", "usage_date" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.usage_date", "payer_account_id" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.payer_account_id", "linked_account_id" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.linked_account_id", "resource_id" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.resource_id", "product_code" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.product_code", "operation" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.operation", "region" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.region", "charge_type" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.charge_type", "pricing_unit" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.pricing_unit", "usage_quantity" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.usage_quantity", "unblended_cost" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.unblended_cost", "public_cost" AS "ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.public_cost"
FROM "cid_cur"."s3_view"
) AS "t"
LEFT JOIN (
SELECT "account_id" AS "4559aa95-4a54-4998-800b-5fd03af260ea.account_id", "parent_account_id" AS "4559aa95-4a54-4998-800b-5fd03af260ea.parent_account_id", "account_name" AS "4559aa95-4a54-4998-800b-5fd03af260ea.account_name", "account_email_id" AS "4559aa95-4a54-4998-800b-5fd03af260ea.account_email_id"
FROM "cid_cur"."account_map"
) AS "t0" ON "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.linked_account_id" = "t0"."4559aa95-4a54-4998-800b-5fd03af260ea.account_id"
LEFT JOIN (
SELECT "account_id" AS "e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.account_id", "account_name" AS "e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.account_name", "ou" AS "e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.ou", "ou_id" AS "e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.ou_id", "payer_org_account_id" AS "e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.payer_org_account_id", "management_account_id" AS "e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.management_account_id"
FROM "AwsDataCatalog"."optimization_data"."organization_map"
) AS "t1" ON "t"."ea0d1482-1bf2-46ee-8dc4-5aaea2ab2209.linked_account_id" = "t1"."e06e4ecb-ebe5-4201-bc39-d9a49cc286b2.account_id"

