FROM (SELECT 1 AS "COL") AS "SUBQUERY"

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::579c4937215f39a289b243981fbc478f89495670bd32607446aba9763f847da3 */
select strategy_group_id, min(date_) as min_date, max(date_) as max_date
                from cmf.mdr_ibor_data_tfm where strategy_group_id in ('tfm_ai_long_short') group by strategy_group_id

/* cppi::eae151a6d6dc64d3b352b2dabaebbe59d69ab6deb58464d470ef5c1fcd5be22f */
select security_id, barra_id from asset.cppib_asset_vendor_id_mapping where pit_date = date'2025-06-23' 
                                      and market_status='ACTV' and primary_flg='Y' and trading_item_id is not null

/* cppi::66789de2a6f789bb00f8469927b06d7c014d17cf9d8c3ec1fba6b92b8440284f */
select business_date as date_, security_id, id_vendor_security_eod, id_vendor_security_ndo, bloomberg_ticker, id_sedol_eod, id_sedol_ndo, weight_eod, weight_ndo, country_listing
 from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, 
                id_vendor_security_ndo order by feed_version asc, id_cppib_index desc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                where business_date = date '2025-06-23'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::f0608ee181f5174c1318a7209c2546d4c918ee8dc748ecd0668e2d82fb557949 */
select cntry ,del_dt, * from asset.asset_security_identifiers_universe where cppib_sec_id = 518575
LIMIT 200

/* cppi::30724e3a6efeb6e10e84adaf2acd99dfae0568c93a5104c67e2d0ee1c6c3cba0 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-12' and end_date = '2025-05-12')
and start_date = '2025-05-12' and end_date = '2025-05-12'

/* cppi::d83f7ae2fb9d1104ddb0e0e899b5f61948280d107138356afa208f482f5be375 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2024-05-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-03-03'
    ) a
where arrival_time = max_publish
